INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6047498, 886626, 39057, '<td valign="top">Amazing what a fraction of an inch can do...If this had been cropped about 1/4 inch tighter on the bottom it would have been a disaster. If you notice, you can see the "baby fat" lines right above the border...with a hint of the rest of the leg touching the border..<br/> <br/>...if that hint of the rest of the legs..and up towards the hips would had been cut off, it would have looked as though the mother was holding two "amputated" legs....this would have scored a 5 IMO....<br/> <br/>....however, as it is, I say a 7.<br/> <br/>I''m sure you''re saying..."what the hell is this guy talking about" !!!</td>', 'Amazing what a fraction of an inch can do...If this had been cropped about 1/4 inch tighter on the bottom it would have been a disaster. If you notice, you can see the "baby fat" lines right above the border...with a hint of the rest of the leg touching the border.. ...if that hint of the rest of the legs..and up towards the hips would had been cut off, it would have looked as though the mother was holding two "amputated" legs....this would have scored a 5 IMO.... ....however, as it is, I say a 7. I''m sure you''re saying..."what the hell is this guy talking about" !!!', '2010-06-09 01:00:00.000000', NULL, 1),
(6047504, 886626, 39057, '<td valign="top">I moved my vote from an 7 to a 10 with 5 seconds left....can someone calculate if that pushed it over the top?<br/><br/><i>Message edited by author 2010-06-09 00:02:48.</i></td>', 'I moved my vote from an 7 to a 10 with 5 seconds left....can someone calculate if that pushed it over the top?', '2010-06-09 01:02:29.000000', '2010-06-09 01:02:48.000000', 0),
